  "subscribe.invalidBody": "ਤੁਹਾਡੇ ਵੱਲੋਂ ਅਪਣਾਇਆ ਗਿਆ ਲਿੰਕ ਸਾਡੇ ਵੱਲੋਂ ਪੇਸ਼ ਕੀਤੀ ਕਿਸੇ ਯੋਜਨਾ ਦਾ ਨਾਮ ਨਹੀਂ ਦਿੰਦਾ। ਜਾਰੀ ਰੱਖਣ ਲਈ ਹੇਠਾਂ ਇੱਕ ਚੁਣੋ — ਕਿਸੇ ਚੀਜ਼ ਦੀ ਗਾਹਕੀ ਨਹੀਂ ਲਈ ਗਈ ਹੈ।",
