  "plans.intro": "ਇੱਕ ਖਾਤਾ, ਤੁਸੀਂ ਜੋ ਵੀ ਯੋਜਨਾ ਚੁਣੋ — Business ਪੰਜ ਕਾਰੋਬਾਰਾਂ ਤੱਕ ਨੂੰ ਕਵਰ ਕਰਦਾ ਹੈ। ਕੀਮਤਾਂ ਅਮਰੀਕੀ ਡਾਲਰਾਂ ਵਿੱਚ ਮਹੀਨਾਵਾਰ ਹਨ, ਅਤੇ ਯੋਗ ਨਵੇਂ ਵੈੱਬਸਾਈਟ ਗਾਹਕਾਂ ਨੂੰ Essentials ਅਤੇ Business ਵਿੱਚ ਇੱਕ ਸੱਤ-ਦਿਨ ਦੀ ਅਜ਼ਮਾਇਸ਼ ਮਿਲ ਸਕਦੀ ਹੈ। ਮੌਜੂਦਾ Essentials ਗਾਹਕੀ ਨੂੰ Business ਵਿੱਚ ਅੱਪਗ੍ਰੇਡ ਕਰਨ ਨਾਲ ਅਜ਼ਮਾਇਸ਼ ਦੁਬਾਰਾ ਸ਼ੁਰੂ ਨਹੀਂ ਹੁੰਦੀ ਅਤੇ ਨਾ ਹੀ ਕੋਈ ਹੋਰ ਮੁਫ਼ਤ ਅਜ਼ਮਾਇਸ਼ ਬਣਦੀ ਹੈ। ਵੈੱਬਸਾਈਟ ਯੋਜਨਾ ਦੀਆਂ ਕੀਮਤਾਂ ਲਾਗੂ ਟੈਕਸਾਂ ਤੋਂ ਪਹਿਲਾਂ ਦੀਆਂ ਹਨ, ਜੇ ਕੋਈ ਹੋਣ। ਗਾਹਕੀ ਨੂੰ ਅਧਿਕਾਰਤ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਤੁਹਾਡਾ ਸਹੀ ਚਾਰਜ ਵਿਖਾਇਆ ਜਾਵੇਗਾ।",
