  "print.footerPacking": "ਹਰ ਲਾਈਨ ਨੂੰ ਡੱਬੇ ਵਿੱਚ ਜਾਂਦਿਆਂ ਨਿਸ਼ਾਨ ਲਗਾਓ, ਫਿਰ ਆਰਡਰ ਨੂੰ ਭੇਜਿਆ ਵਜੋਂ ਨਿਸ਼ਾਨ ਲਗਾਓ ਤਾਂ ਜੋ ਸਟਾਕ ਇੱਕ ਵਾਰ ਨਿਕਲੇ।",
