  "settings.delete.title": "ਖਾਤਾ ਮਿਟਾਓ",
  "settings.delete.underReview": "ਤੁਹਾਡੀ ਖਾਤਾ ਮਿਟਾਉਣ ਦੀ ਬੇਨਤੀ ਸਮੀਖਿਆ ਅਧੀਨ ਹੈ।",
  "settings.deletion.checkError": "ਇਸ ਸਮੇਂ ਮੌਜੂਦਾ ਬੇਨਤੀਆਂ ਦੀ ਜਾਂਚ ਨਹੀਂ ਕੀਤੀ ਜਾ ਸਕਦੀ। ਤੁਸੀਂ ਫਿਰ ਵੀ ਬੇਨਤੀ ਜਮ੍ਹਾਂ ਕਰਨ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰ ਸਕਦੇ ਹੋ।",
  "settings.deletion.confirmError": "ਅਸੀਂ ਤੁਹਾਡੀ ਮਿਟਾਉਣ ਦੀ ਬੇਨਤੀ ਦੀ ਪੁਸ਼ਟੀ ਨਹੀਂ ਕਰ ਸਕੇ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
