  "staff.access.noSeatBody": "ਤੁਹਾਡੇ ਖਾਤੇ ਕੋਲ ਇਸ ਕਾਰੋਬਾਰ ਲਈ ਕੋਈ ਸਟਾਫ਼ ਸੀਟ ਨਹੀਂ ਹੈ, ਇਸ ਲਈ ਇਸਦਾ ਸਟਾਕ ਬੰਦ ਰਹਿੰਦਾ ਹੈ। ਮਾਲਕ ਨੂੰ ਕਹੋ ਕਿ ਉਹ ਤੁਹਾਨੂੰ ਸਟਾਫ਼ ਅਤੇ ਭੂਮਿਕਾਵਾਂ ਵਿੱਚ ਸ਼ਾਮਲ ਕਰੇ।",
