  "staff.emptyTitle": "ਅਜੇ ਕੋਈ ਸਟਾਫ਼ ਨਹੀਂ",
  "staff.eyebrow": "ਟੀਮ",
  "staff.how.p1": "ਹਰ ਮੈਂਬਰ ਕੋਲ ਇੱਕ ਭੂਮਿਕਾ ਅਤੇ ਉਹਨਾਂ ਦੀ ਆਪਣੀ ਇਜਾਜ਼ਤ ਸੂਚੀ ਹੁੰਦੀ ਹੈ, ਇਸ ਲਈ ਤੁਸੀਂ ਇੱਕ ਭੂਮਿਕਾ ਤੋਂ ਸ਼ੁਰੂ ਕਰਕੇ ਨਵੀਂ ਭੂਮਿਕਾ ਬਣਾਏ ਬਿਨਾਂ ਇੱਕ ਚੀਜ਼ ਬਦਲ ਸਕਦੇ ਹੋ। ਭੂਮਿਕਾ ਨੂੰ ਸੰਪਾਦਿਤ ਕਰਨ ਨਾਲ ਪਹਿਲਾਂ ਤੋਂ ਇਸ 'ਤੇ ਮੌਜੂਦ ਮੈਂਬਰ ਦੁਬਾਰਾ ਨਹੀਂ ਲਿਖੇ ਜਾਂਦੇ — ਉਹਨਾਂ ਦੇ ਭੂਮਿਕਾ ਡਿਫੌਲਟ ਦੁਬਾਰਾ ਲਾਗੂ ਕਰਨ ਲਈ ਇੱਕ ਮੈਂਬਰ ਖੋਲ੍ਹੋ।",
  "staff.how.p2": "ਕਸਟਮ ਭੂਮਿਕਾਵਾਂ ਇੱਕ Business ਵਿਸ਼ੇਸ਼ਤਾ ਹਨ: Essentials ਪੰਜ ਬਿਲਟ-ਇਨ ਭੂਮਿਕਾਵਾਂ (ਮਾਲਕ, ਮੈਨੇਜਰ, ਸਟਾਕ ਕਲਰਕ, ਸੇਲਜ਼ ਕਲਰਕ, ਦਰਸ਼ਕ) ਦੀ ਵਰਤੋਂ ਕਰਦਾ ਹੈ।",
  "staff.how.p3": "ਸੱਦੇ ਈਮੇਲ ਰਾਹੀਂ ਭੇਜੇ ਜਾਂਦੇ ਹਨ। ਇੱਕ ਮੈਂਬਰ ਸਿਰਫ਼ ਉਦੋਂ ਸਾਈਨ ਇਨ ਕਰ ਸਕਦਾ ਹੈ ਜਦੋਂ ਉਹ ਸਵੀਕਾਰ ਕਰਦਾ ਹੈ, ਅਤੇ ਕਿਸੇ ਨੂੰ ਇਸ ਸੂਚੀ ਤੋਂ ਹਟਾਉਣ ਨਾਲ ਉਹਨਾਂ ਦਾ ਐਪ ਖਾਤਾ ਨਹੀਂ ਮਿਟਦਾ।",
  "staff.how.p4": "ਇੱਕ ਸਟੋਰ ਉਹ ਸਥਾਨ ਹੈ ਜਿੱਥੇ ਇੱਕ ਵਿਅਕਤੀ ਨੂੰ ਨਿਯੁਕਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਇਹ ਉਹਨਾਂ ਦੇ ਕਾਰਡ 'ਤੇ ਦਰਜ ਹੁੰਦਾ ਹੈ; ਉਹ ਕੀ ਖੋਲ੍ਹ ਸਕਦੇ ਹਨ ਇਹ ਅਜੇ ਵੀ ਉਹਨਾਂ ਦੀ ਭੂਮਿਕਾ ਅਤੇ ਇਜਾਜ਼ਤਾਂ ਦੁਆਰਾ ਤੈਅ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।",
  "staff.how.p5": "ਇਜਾਜ਼ਤਾਂ ਤੈਅ ਕਰਦੀਆਂ ਹਨ ਕਿ ਹਰ ਵਿਅਕਤੀ ਕੀ ਖੋਲ੍ਹ ਸਕਦਾ ਹੈ: ਉਹਨਾਂ ਦੀ ਭੂਮਿਕਾ ਤੋਂ ਬਾਹਰ ਦੇ ਮੀਨੂ ਆਈਟਮ ਲੁਕਾਏ ਜਾਂਦੇ ਹਨ, ਅਤੇ ਇੱਕ ਬਲੌਕ ਕੀਤਾ ਪਤਾ ਪੇਜ ਦੀ ਬਜਾਏ “ਤੁਹਾਡੀ ਭੂਮਿਕਾ 'ਤੇ ਨਹੀਂ” ਨੋਟਿਸ ਦਿਖਾਉਂਦਾ ਹੈ। ਇੱਕ ਬਦਲਾਅ ਅਗਲੀ ਵਾਰ ਲਾਗੂ ਹੁੰਦਾ ਹੈ ਜਦੋਂ ਉਹ ਵਿਅਕਤੀ ਐਪ ਲੋਡ ਕਰਦਾ ਹੈ; ਇੱਕ ਮੈਂਬਰ ਨੂੰ ਮੁਅੱਤਲ ਕਰਨ ਨਾਲ ਉਹ ਪੂਰੀ ਤਰ੍ਹਾਂ ਬਾਹਰ ਹੋ ਜਾਂਦੇ ਹਨ।",
  "staff.how.p6": "ਪ੍ਰਬੰਧਕ ਸਾਰਾ ਡਾਟਾ ਦੇਖ ਅਤੇ ਬਦਲ ਸਕਦੇ ਹਨ, ਐਪ ਉਪਭੋਗਤਾਵਾਂ ਅਤੇ ਭੂਮਿਕਾਵਾਂ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰ ਸਕਦੇ ਹਨ, ਅਤੇ ਕਦੇ ਵੀ ਸਟਾਫ਼ ਭੂਮਿਕਾ ਦੁਆਰਾ ਸੀਮਤ ਨਹੀਂ ਹੁੰਦੇ। ਜਿਸਦੇ ਕੋਲ ਕੋਈ ਸਟਾਫ਼ ਰਿਕਾਰਡ ਨਹੀਂ ਹੈ — ਇੱਕ ਨਵੇਂ ਕਾਰੋਬਾਰ ਦਾ ਮਾਲਕ — ਪੂਰੀ ਪਹੁੰਚ ਰੱਖਦਾ ਹੈ।",
  "staff.howTitle": "ਸਟਾਫ਼ ਅਤੇ ਭੂਮਿਕਾਵਾਂ ਕਿਵੇਂ ਕੰਮ ਕਰਦੀਆਂ ਹਨ",
